import assert from 'node:assert/strict';
import normalizeUrl from '../index.js';

describe('normalizeUrl duplicate slash handling', () => {
  it('should preserve path with multiple protocol-like patterns', () => {
    const input = 'http://example.com/a/http://b/http://c';
    const expected = 'http://example.com/a/http://b/http://c';
    const actual = normalizeUrl(input);
